import assert from'node:assert/strict';import{readFileSync,mkdirSync,writeFileSync}from'node:fs';import{chromium,webkit}from'playwright';import{chapterCollections,chapterHash}from'../lib/practice-chapters.ts';const base=process.env.KLINK_TEST_URL||'http://127.0.0.1:18996',out=process.env.KLINK_ENTER_OUTPUT||'outputs/enter-focus-20261101/audio';mkdirSync(out,{recursive:true});const checks=[];
for(const[engine,type]of Object.entries({chromium,webkit})){const b=await type.launch();try{const p=await b.newPage({viewport:{width:390,height:844},hasTouch:true});await p.addInitScript(()=>{window.__enterMedia=[];const play=HTMLMediaElement.prototype.play;HTMLMediaElement.prototype.play=function(){window.__enterMedia.push(this);return play.call(this)};localStorage.setItem('klink.enter.audio','kept')});const row=chapterCollections('text-question').find(r=>r.id==='klink-teksten-zelf-a1-r01-v1'),es=JSON.parse(readFileSync('public'+row.contentUrl)).exercises,e=es[0];await p.goto(base+'/'+chapterHash({chapter:'texts',activity:'text-question',collection:row.id,level:row.level,help:'practice'}));await p.locator('[data-exercise-id]').waitFor();await p.locator('[data-practice-listen]').first().click();await p.waitForFunction(()=>window.__enterMedia.some(a=>!a.paused&&!a.ended));await p.locator('.cp-choice-grid > .cp-extended-option > button:first-child').nth(e.options.findIndex(o=>e.answer.correctOptionIds.includes(o.id))).click();assert.equal(await p.locator('[data-exercise-id]').getAttribute('data-practice-ready'),'true');assert(await p.evaluate(()=>window.__enterMedia.some(a=>!a.paused&&!a.ended)),'Audio must still play before Enter');await p.keyboard.press('Enter');await p.waitForTimeout(150);assert.equal(await p.locator('[data-exercise-id]').getAttribute('data-exercise-id'),es[1].exerciseId);assert(await p.evaluate(()=>window.__enterMedia.every(a=>a.paused||a.ended)),'Previous audio stops on next');assert.equal(await p.evaluate(()=>localStorage.getItem('klink.enter.audio')),'kept');checks.push({engine,nativeAudio:true,enterAfterCorrectWhilePlaying:true,exactlyOneNext:true,oldAudioStopped:true,storagePreserved:true});await p.close();}finally{await b.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,errors:[]},null,2)+'\n');}}
assert.equal(checks.length,2);console.log('PASS 2 real reading-audio/Enter flows.');
